css:
/* Шаги с липким кадром. База — стопка «кадр → шаг» (без JS, телефон, печать): всё видно, ничего не движется.
   Липкая раскладка включается классом .is-live (ставит скрипт) и только на экране от 900px.
   Предки секции НЕ должны иметь overflow: hidden/auto — это выключает sticky; для горизонтали — overflow-x: clip. */
.sst {
  --sst-beat: 72vh;                          /* прокрутка на шаг: 600–1000px; меньше — шаги пролетают, больше — «страница зависла» */
  --sst-top: 14vh;                           /* где встаёт кадр; под липкой шапкой — не меньше её высоты + 16px */
  --sst-radius: 20px;
  --sst-in: 400ms;                           /* кадр проявляется */
  --sst-out: 260ms;                          /* уходит быстрее: 65–75 % от появления */
  --sst-ease-in: cubic-bezier(.2, 0, 0, 1);  /* появление — с торможением */
  --sst-ease-out: cubic-bezier(.4, 0, 1, 1); /* уход — с разгоном */
  padding-block: 64px;
}
.sst__title { margin: 0 0 32px; font-size: clamp(28px, 3.4vw, 44px); line-height: 1.15; }
.sst__grid { display: grid; gap: 16px; max-width: 720px; margin-inline: auto; }
.sst__steps, .sst__media { display: contents; } /* в стопке кадры и шаги встают в один ряд, порядок задаёт order ниже */
.sst__fig {
  margin: 0;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  overflow: clip;
  border-radius: var(--sst-radius);
  background: var(--surface, #f2f3f5); /* заглушка до загрузки кадра */
}
.sst__fig img { display: block; width: 100%; height: 100%; object-fit: cover; }
.sst__step { padding: 4px 0 32px; }
.sst__body { position: relative; }
.sst__num {
  display: inline-grid; place-items: center;
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--border, #d9dce3);
  font-size: 15px; font-weight: 600;
}
.sst__step h3 { margin: 12px 0 8px; font-size: clamp(22px, 2.4vw, 30px); line-height: 1.2; }
.sst__step p { margin: 0; max-width: 42ch; color: var(--text-muted, #555b66); }
/* стопка: кадр 1, шаг 1, кадр 2, шаг 2… (до 4 шагов) */
.sst__fig:nth-child(1) { order: 1; } .sst__step:nth-child(1) { order: 2; }
.sst__fig:nth-child(2) { order: 3; } .sst__step:nth-child(2) { order: 4; }
.sst__fig:nth-child(3) { order: 5; } .sst__step:nth-child(3) { order: 6; }
.sst__fig:nth-child(4) { order: 7; } .sst__step:nth-child(4) { order: 8; }

@media screen and (min-width: 900px) {
  .sst.is-live .sst__grid {
    grid-template-columns: minmax(0, 5fr) minmax(0, 6fr);
    column-gap: clamp(32px, 5vw, 80px);
    align-items: start;
    max-width: none;
  }
  .sst.is-live .sst__steps { display: block; grid-area: 1 / 1; }
  .sst.is-live .sst__media { display: grid; grid-area: 1 / 2; position: sticky; top: var(--sst-top); }
  .sst.is-live .sst__step {
    min-height: var(--sst-beat);
    display: flex; flex-direction: column; justify-content: center;
    padding: 0;
  }
  .sst.is-live .sst__body { padding-left: 28px; }
  /* отметка текущего шага: полоса слева вырастает сверху вниз */
  .sst.is-live .sst__body::before {
    content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; border-radius: 3px;
    background: var(--primary, #2446d8);
    transform: scaleY(0); transform-origin: 50% 0;
    transition: transform var(--sst-out) var(--sst-ease-out);
  }
  .sst.is-live .sst__step.is-on .sst__body::before { transform: none; transition: transform var(--sst-in) var(--sst-ease-in); }
  /* кадры лежат друг на друге в одной ячейке: смена — проявлением, уходящий гаснет быстрее */
  .sst.is-live .sst__fig {
    grid-area: 1 / 1;
    max-height: calc(100vh - var(--sst-top) - 24px);
    opacity: 0;
    transform: scale(1.03);
    transition: opacity var(--sst-out) var(--sst-ease-out), transform var(--sst-out) var(--sst-ease-out);
  }
  .sst.is-live .sst__fig.is-on {
    opacity: 1;
    transform: none;
    transition: opacity var(--sst-in) var(--sst-ease-in) 80ms, transform calc(var(--sst-in) * 1.4) var(--sst-ease-in) 80ms; /* перехлёст 80ms */
  }
}

/* Уменьшение движения (уровень «смягчить»): кадры меняются только прозрачностью за 150ms, без масштаба; отметка шага — сразу */
@media (prefers-reduced-motion: reduce) {
  .sst.is-live .sst__fig,
  .sst.is-live .sst__fig.is-on { transform: none; transition: opacity 150ms linear; }
  .sst.is-live .sst__body::before,
  .sst.is-live .sst__step.is-on .sst__body::before { transition: none; }
}

