// Шаги с липким кадром: без зависимостей. Прилипание делает CSS (sticky), скрипт только решает, какой шаг текущий.
(() => {
  document.querySelectorAll('[data-sst]').forEach((root) => {
    const steps = [...root.querySelectorAll('[data-sst-step]')];
    const figs = [...root.querySelectorAll('[data-sst-fig]')];
    if (!steps.length || !('IntersectionObserver' in window)) return; // без IO остаётся стопка, всё видно
    let cur = -1;
    const set = (i) => {
      if (i < 0 || i === cur) return;
      cur = i;
      steps.forEach((s, k) => {
        s.classList.toggle('is-on', k === i);
        if (k === i) s.setAttribute('aria-current', 'step'); else s.removeAttribute('aria-current');
      });
      figs.forEach((f) => f.classList.toggle('is-on', +f.dataset.sstFig === i));
    };
    // Текущий — шаг, который пересекает полосу в середине экрана (45–46 % высоты)
    const io = new IntersectionObserver((es) => es.forEach((e) => {
      if (e.isIntersecting) set(steps.indexOf(e.target));
    }), { rootMargin: '-45% 0px -54% 0px' });
    steps.forEach((s) => io.observe(s));
    // Tab по ссылке внутри шага: кадр подстраивается под шаг с фокусом
    root.addEventListener('focusin', (e) => set(steps.indexOf(e.target.closest('[data-sst-step]'))));
    set(0);
    root.classList.add('is-live'); // включает липкую раскладку (только от 900px)
  });
})();

