// Только если GSAP уже есть в проекте: npm i gsap (Standard License, не MIT), без CDN. Разметка и CSS те же, JS рецепта не подключать.
// Прилипание по-прежнему делает CSS (sticky); ScrollTrigger только переключает текущий шаг. pin не нужен.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);

const root = document.querySelector('[data-sst]');
const steps = gsap.utils.toArray('[data-sst-step]', root);
const figs = gsap.utils.toArray('[data-sst-fig]', root);
const set = (i) => {
  steps.forEach((s, k) => { s.classList.toggle('is-on', k === i); k === i ? s.setAttribute('aria-current', 'step') : s.removeAttribute('aria-current'); });
  figs.forEach((f) => f.classList.toggle('is-on', +f.dataset.sstFig === i));
};
set(0);
root.classList.add('is-live');
steps.forEach((s, i) => ScrollTrigger.create({
  trigger: s, start: 'top 45%', end: 'bottom 45%', // та же полоса у середины экрана, что в ванильной версии
  onToggle: (self) => self.isActive && set(i),
}));
// Уменьшение движения отдельно обрабатывать не нужно: переходы кадров задаёт CSS, и он сам смягчает их под reduce.
